Here’s a **simple and clean C++ version** of Kadane’s Algorithm that also **prints the subarray** which gives the maximum sum:

```cpp
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> arr = {-2, 1, -3, 4, -1, 2, 1, -5, 4};

    int maxSum = arr[0], currSum = arr[0];
    int start = 0, end = 0, tempStart = 0;

    for (int i = 1; i < arr.size(); i++) {
        if (currSum < 0) {
            currSum = arr[i];
            tempStart = i;
        } else {
            currSum += arr[i];
        }

        if (currSum > maxSum) {
            maxSum = currSum;
            start = tempStart;
            end = i;
        }
    }

    cout << "Max Sum: " << maxSum << endl;
    cout << "Subarray: ";
    for (int i = start; i <= end; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}
```

---

### 🧪 Output for the example:
```
Max Sum: 6
Subarray: 4 -1 2 1
```

